    $this->hours += $interval->h * $sign;
    $this->minutes += $interval->i * $sign;
    $this->seconds += $interval->s * $sign;
    $this->microseconds += $interval->microseconds * $sign;

    $this->solveNegativeInterval();

    return $this;
}

